Action.ExecScriptExpression:
using System;
using System.Collections.Generic;
using System.Linq;
using System.Numerics;
using Triggernometry.Core;
using Triggernometry.Core.Scripting;
using Triggernometry.Expressions.String.Models;
using Triggernometry.Expressions.String.Utils;
using Triggernometry.PluginBridges.BridgeNamazu.Vfx;
using Triggernometry.Utilities.Maths;

RealPlugin.Instance.RegisterNamedCallback(
    "新月_扫雷", new Action<object, string>(MineSweeper.Callback), null, false, "新月岛宝宝椅"
);

public class Mine
{
    public float ExplodeRadius => IsLarge ? 30f : 7f;
    public Vector3 Pos { get; set; }
    public bool IsLarge { get; set; }
    public bool IsInRange(Vector3 knownPos, double range)
    {
        // 平面距离小于阈值，且高度差小于 10 m
        var dx = knownPos.X - Pos.X;
        var dy = knownPos.Y - Pos.Y;
        var dz = Math.Abs(knownPos.Z - Pos.Z);

        return dx * dx + dy * dy <= range * range && dz <= 10;
    }

    public Mine(double x, double y, double z, bool isLarge)
    {
        Pos = new Vector3((float)x, (float)y, (float)z);
        IsLarge = isLarge;
    }
    public Mine((double, double, double, bool) rawData)
        : this(rawData.Item1, rawData.Item2, rawData.Item3, rawData.Item4) { }

    // 状态相关：

    /// <summary> 是否可以确定其是否存在 </summary>
    public bool? Exist { get; set; } = null;
    /// <summary> 是否已经被游戏显示（或已爆炸），即不需要再显示此特效 </summary>
    public bool ShownByGame { get; set; } = false;

    // 特效相关：

    StaticVfx vfx;
    public void InitVfx()
    {
        if (vfx != null) RemoveVfx();
        vfx = StaticVfx.Create("vfx/omen/eff/m0777cir_a_o0c.avfx", "新月_Mine");
        vfx.Run();
        vfx.Pos = Pos;
        vfx.Scales = new Vector3(4, 4, 5);
        vfx.Color = IsLarge ? new Vector4(1f, 0.4f, 0.7f, 1f) : new Vector4(0.7f, 1f, 0.2f, 1f); // 红/黄
        UpdateVfxByState();
    }

    public void UpdateVfxByState()
    {
        if (vfx == null) return;
        bool shouldDisplay = Exist == false ? false : !ShownByGame;
        var color = vfx.Color;
        color.W = shouldDisplay ? 1f : 0f;
        vfx.Color = color;
        vfx.Update();
    }

    public void RemoveVfx()
    {
        vfx?.TryRemove();
        vfx = null;
    }

}

public class MineGroup
{
    //public bool IsLarge => Mines.First().IsLarge;
    public int MaxCount { get; set; }
    public List<Mine> Mines { get; set; }
    public bool Resolved { get; set; }
    public MineGroup(int maxCount, params (double, double, double, bool)[] minesData)
    {
        Mines = minesData.Select(data => new Mine(data)).ToList();
        MaxCount = maxCount;
    }

    public void InitVfx()
    {
        Mines.ForEach(m => m.InitVfx());
    }

    public void UpdateVfxByState()
    {
        Mines.ForEach(m => m.UpdateVfxByState());
    }

    public void RemoveVfx()
    {
        Mines.ForEach(m => m.RemoveVfx());
    }

    void AnalyzeState()
    {
        var exist = new List<Mine>();
        var others = new List<Mine>();

        foreach (var m in Mines)
        {
            if (m.Exist == true)
                exist.Add(m);
            else
                others.Add(m);
        }

        if (exist.Count >= MaxCount)
        {
            foreach (var m in others)
            {
                m.Exist = false;
            }
        }
        if (exist.Count > MaxCount)
        {
            ScriptHelper.Log(RealPlugin.DebugLevelEnum.Error,
                $"组内记录到的雷数高于最大数目：\n{string.Join("; \n", exist.Select(m => m.Pos))}");
        }
        UpdateVfxByState();
    }

    public bool TryApplyScan(Vector3 scanPos, double range)
    {
        var minesInRange = Mines.Where(mine => mine.IsInRange(scanPos, range)).ToList();
        if (minesInRange.Any())
        {
            foreach (var m in minesInRange)
            {
                if (m.Exist == null)
                    m.Exist = false;
            }
            AnalyzeState();
            return true;
        }
        return false;
    }

    public Mine Found(Vector3 pos, bool isLarge)
    {
        var minesInRange = Mines.Where(mine => mine.IsInRange(pos, 1) && isLarge == mine.IsLarge).ToList();
        if (minesInRange.Count > 1)
            throw new Exception("扫描到超过一个雷，疑似数据有误。");
        var foundMine = minesInRange.FirstOrDefault();
        if (foundMine != null)
        {
            foundMine.ShownByGame = true;
            foundMine.Exist = true;
            AnalyzeState();
        }
        return foundMine;
    }
}

public static class MineSweeper
{
    static Dictionary<int, List<MineGroup>> MineData;
    static object _lock = new object();

    public static void Callback(object o, string command)
    {
        var data = new MultiLineRawArgs(command);
        var action = data.Get("action").ToLower();
        lock (_lock)
        {
            switch (action)
            {
                case "init":
                    InitMineData();
                    return;
                case "changemap":
                    ChangeMap(data);
                    return;
                case "scan":
                    Scan(data);
                    return;
                case "found":
                    Found(data);
                    return;
                case "end":
                    End();
                    return;
                default:
                    throw new NotImplementedException(action);
            }
        }
    }

