    }

    static int prevMapId = 0;
    // 只会在
    public static void ChangeMap(MultiLineRawArgs data)
    {
        if (MineData == null) InitMineData();

        var mapId = data.Get("mapId").ParseData<int>();
        if (prevMapId == mapId) return;

        if (MineData.TryGetValue(mapId, out var currGroups))
        {
            currGroups.ForEach(g => g.InitVfx());
        }
        if (MineData.TryGetValue(prevMapId, out var prevGroups))
        {
            prevGroups.ForEach(g => g.RemoveVfx());
        }
        prevMapId = mapId;
    }

    public static void Scan(MultiLineRawArgs data)
    {
        if (MineData == null) InitMineData();

        var pos = (Vector3)XIVCoord.ParseRawData(data.Get("pos"));
        var range = data.Get("isHunter").ParseData<bool>() ? 9f : 15f; // 魔猎鹰半径 5 + 雷半径 4 = 9；探测以雷中心为准所以不加半径
        foreach (var group in MineData.SelectMany(pair => pair.Value))
        {
            group.TryApplyScan(pos, range);
        }
    }

    public static void Found(MultiLineRawArgs data)
    {
        if (MineData == null) InitMineData();

        var pos = (Vector3)XIVCoord.ParseRawData(data.Get("pos"));
        var isLarge = data.Get("isLarge").ParseData<bool>();
        foreach (var group in MineData.SelectMany(pair => pair.Value))
        {
            if (group.Found(pos, isLarge) != null)
            {
                break;
            }
        }
    }

    public static void End()
    {
        if (MineData == null) return;
        foreach (var group in MineData.SelectMany(kvp => kvp.Value))
        {
            group.RemoveVfx();
        }
        MineData = null;
    }

}

