Action.ExecScriptExpression:
using System;
using Triggernometry.PluginBridges.BridgeNamazu.Modules;

var m = new ForayLevelModule();
m.Scan();
m.RegisterAnnotatedMethods();

public class ForayLevelModule : ModuleBase
{
    public int IsCastingOffset;
    public ForayLevelModule()
    {
        ScanMethod = () =>
        {
            IsCastingOffset = Triggernometry.FFXIV.Entity.FieldOffset("IsCasting1")
                ?? Triggernometry.FFXIV.Entity.FieldOffset("CastFlags")
                ?? Triggernometry.FFXIV.Entity.FieldOffset("CastInfo")
                ?? throw new Exception("IsCasting Offset not found");
        };
    }

    [ScriptingMethod("GetForayLevel")]
    public byte GetForayLevel()
    {
        if (IsCastingOffset == 0) return 0;

        // 从 6.x 到 7.x 保持稳定的差值
        // FFXIVClientStructs.FFXIV.Client.Game.Character.BattleChara
        // [FieldOffset(0x2790)] public CastInfo CastInfo;
        // [FieldOffset(0x3800)] public ForayInfo ForayInfo;
        var forayLevelOffset = IsCastingOffset + (0x3800 - 0x2790);
        var address = Triggernometry.FFXIV.Entity.GetMyself().Address + forayLevelOffset;
        return Memory.Read<byte>(address);
    }

    [ScriptingMethod("GetAdjustedForayLevel")]
    public byte GetAdjustedForayLevel()
    {
        if (IsCastingOffset == 0) return 0;
        var forayLevelOffset = IsCastingOffset + (0x3800 - 0x2790) + 2;
        var address = Triggernometry.FFXIV.Entity.GetMyself().Address + forayLevelOffset;
        return Memory.Read<byte>(address);
    }

}

